/// ParseError for invalid TOML input
suberror ParseError {
  InvalidToken(Int, String)
  DuplicateKey(Int, String)
  Unexpected(Int, String)
  UnterminatedString(Int)
} derive(Debug)

///|
fn parse_error(pos : Int, msg : String) -> ParseError {
  ParseError::InvalidToken(pos, msg)
}

///|
fn dup_key_error(pos : Int, key : String) -> ParseError {
  ParseError::DuplicateKey(pos, key)
}

// --------------- lexer ---------------

///|
enum Token {
  Key(String)
  DottedKeyStart(String)
  DottedKeyPart(String)
  Eq
  StringValue(String)
  IntValue(Int)
  BoolValue(Bool)
  ArrayStart
  ArrayEnd
  Comma
  TableStart
  TableEnd
  Newline
  Eof
}

///|
fn lex(text : String) -> Array[Token] raise ParseError {
  let mut tokens : Array[Token] = []
  let mut i = 0
  let len = text.length()
  while i < len {
    let ch = text[i]
    // whitespace (space, tab) but not newline
    if ch == ' ' || ch == '\t' || ch == '\r' {
      i += 1
    } else if ch == '\n' {
      tokens.push(Token::Newline)
      i += 1
    } else if ch == '#' {
      // comment until newline
      while i < len && text[i] != '\n' {
        i += 1
      }
    } else if ch == '=' {
      tokens.push(Token::Eq)
      i += 1
    } else if ch == '[' {
      // check for [[ (array of tables) - skip for now
      if i + 1 < len && text[i + 1] == '[' {
        // skip [[...]]
        i += 1
        while i < len && text[i] != ']' {
          i += 1
        }
        while i < len && text[i] == ']' {
          i += 1
        }
      } else {
        tokens.push(Token::TableStart)
        i += 1
      }
    } else if ch == ']' {
      tokens.push(Token::TableEnd)
      i += 1
    } else if ch == ',' {
      tokens.push(Token::Comma)
      i += 1
    } else if ch == '"' {
      // string
      let mut s = StringBuilder::new()
      i += 1 // skip opening quote
      while i < len {
        let c = text[i]
        if c == '"' {
          i += 1
          break
        } else if c == '\\' {
          i += 1
          if i >= len {
            raise ParseError::UnterminatedString(i)
          }
          let esc = text[i]
          match esc {
            '"' => s.write_char('"')
            '\\' => s.write_char('\\')
            'n' => s.write_char('\n')
            't' => s.write_char('\t')
            _ => {
              s.write_char(esc)
            }
          }
          i += 1
        } else {
          s.write_char(c.to_char())
          i += 1
        }
      }
      tokens.push(Token::StringValue(s.to_string()))
    } else if ch == 't' || ch == 'f' {
      // boolean or bare key
      let mut s = StringBuilder::new()
      while i < len {
        let c = text[i]
        if c.is_alphanumeric() || c == '_' || c == '-' {
          s.write_char(c.to_char())
          i += 1
        } else {
          break
        }
      }
      let word = s.to_string()
      if word == "true" {
        tokens.push(Token::BoolValue(true))
      } else if word == "false" {
        tokens.push(Token::BoolValue(false))
      } else {
        tokens.push(Token::Key(word))
      }
    } else if ch.is_digit() || ch == '-' || ch == '+' {
      // integer or negative sign
      let mut s = StringBuilder::new()
      // include sign
      if ch == '-' || ch == '+' {
        s.write_char(ch.to_char())
        i += 1
      }
      while i < len {
        let c = text[i]
        if c.is_digit() || c == '_' {
          if c != '_' {
            s.write_char(c.to_char())
          }
          i += 1
        } else {
          break
        }
      }
      let num_str = s.to_string()
      // Could be a key if followed by '.' or '='
      // but let's try parsing as int
      let n : Int = @string.from_str(num_str) catch {
        _ => {
          // fallback: treat as key
          tokens.push(Token::Key(num_str))
          continue
        }
      }
      tokens.push(Token::IntValue(n))
    } else if ch.is_alpha() || ch == '_' {
      // bare key
      let mut s = StringBuilder::new()
      while i < len {
        let c = text[i]
        if c.is_alphanumeric() || c == '_' || c == '-' {
          s.write_char(c.to_char())
          i += 1
        } else {
          break
        }
      }
      tokens.push(Token::Key(s.to_string()))
    } else if ch == '.' {
      tokens.push(Token::DottedKeyPart("."))
      i += 1
    } else {
      // skip unknown
      i += 1
    }
  }
  tokens.push(Token::Eof)
  tokens
}

// --------------- parser ---------------

///|
struct Entry {
  keys : Array[String]
  value : Json
}

///|
fn consume_newlines(tokens : Array[Token], pos : ref[Int]) {
  while pos.val < tokens.length() {
    match tokens[pos.val] {
      Token::Newline => pos.val += 1
      _ => break
    }
  }
}

///|
fn parse_table_header(tokens : Array[Token], pos : ref[Int]) -> Array[String] raise ParseError {
  // expect TableStart, keys, TableEnd
  if pos.val >= tokens.length() || not (tokens[pos.val] is Token::TableStart) {
    raise parse_error(pos.val, "expected '['")
  }
  pos.val += 1
  let mut keys : Array[String] = []
  // parse first key
  match tokens[pos.val] {
    Token::Key(k) => {
      keys.push(k)
      pos.val += 1
    }
    Token::StringValue(s) => {
      keys.push(s)
      pos.val += 1
    }
    _ => raise parse_error(pos.val, "expected key in table header")
  }
  // parse dotted parts
  while pos.val < tokens.length() {
    match tokens[pos.val] {
      Token::DottedKeyPart(_) => {
        pos.val += 1
        match tokens[pos.val] {
          Token::Key(k) => {
            keys.push(k)
            pos.val += 1
          }
          Token::StringValue(s) => {
            keys.push(s)
            pos.val += 1
          }
          _ => raise parse_error(pos.val, "expected key after dot")
        }
      }
      _ => break
    }
  }
  // expect TableEnd
  if pos.val >= tokens.length() || not (tokens[pos.val] is Token::TableEnd) {
    raise parse_error(pos.val, "expected ']'")
  }
  pos.val += 1
  // expect newline or eof
  consume_newlines(tokens, pos)
  keys
}

///|
fn parse_value(tokens : Array[Token], pos : ref[Int]) -> Json raise ParseError {
  match tokens[pos.val] {
    Token::StringValue(s) => {
      pos.val += 1
      Json::string(s)
    }
    Token::IntValue(n) => {
      pos.val += 1
      Json::number(n.to_double())
    }
    Token::BoolValue(b) => {
      pos.val += 1
      Json::boolean(b)
    }
    Token::ArrayStart => {
      pos.val += 1
      let mut arr : Array[Json] = []
      // skip newlines
      consume_newlines(tokens, pos)
      if pos.val < tokens.length() && tokens[pos.val] is Token::ArrayEnd {
        pos.val += 1
        return Json::array(arr)
      }
      loop {
        let val = parse_value(tokens, pos)
        arr.push(val)
        consume_newlines(tokens, pos)
        if pos.val < tokens.length() && tokens[pos.val] is Token::Comma {
          pos.val += 1
          consume_newlines(tokens, pos)
          if pos.val < tokens.length() && tokens[pos.val] is Token::ArrayEnd {
            pos.val += 1
            break
          }
        } else if pos.val < tokens.length() && tokens[pos.val] is Token::ArrayEnd {
          pos.val += 1
          break
        } else {
          raise parse_error(pos.val, "expected ',' or ']' in array")
        }
      }
      Json::array(arr)
    }
    _ => raise parse_error(pos.val, "expected a value")
  }
}

///|
fn parse_key_value(tokens : Array[Token], pos : ref[Int]) -> (Array[String], Json) raise ParseError {
  let mut keys : Array[String] = []
  // parse first key
  match tokens[pos.val] {
    Token::Key(k) => {
      keys.push(k)
      pos.val += 1
    }
    Token::StringValue(s) => {
      keys.push(s)
      pos.val += 1
    }
    _ => raise parse_error(pos.val, "expected key")
  }
  // parse dotted key parts
  while pos.val < tokens.length() {
    match tokens[pos.val] {
      Token::DottedKeyPart(_) => {
        pos.val += 1
        match tokens[pos.val] {
          Token::Key(k) => {
            keys.push(k)
            pos.val += 1
          }
          Token::StringValue(s) => {
            keys.push(s)
            pos.val += 1
          }
          _ => raise parse_error(pos.val, "expected key after dot")
        }
      }
      _ => break
    }
  }
  // expect '='
  if pos.val >= tokens.length() || not (tokens[pos.val] is Token::Eq) {
    raise parse_error(pos.val, "expected '='")
  }
  pos.val += 1
  let value = parse_value(tokens, pos)
  // consume trailing newline
  if pos.val < tokens.length() && tokens[pos.val] is Token::Newline {
    pos.val += 1
  }
  (keys, value)
}

// --------------- nested map helpers ---------------

///|
fn set_nested(map : Map[String, Json], keys : Array[String], value : Json) raise ParseError {
  _set_nested(map, keys, 0, value)
}

///|
fn _set_nested(map : Map[String, Json], keys : Array[String], idx : Int, value : Json) raise ParseError {
  if idx == keys.length() - 1 {
    let key = keys[idx]
    if map.contains(key) {
      raise dup_key_error(0, key)
    }
    map[key] = value
  } else {
    let key = keys[idx]
    if map.contains(key) {
      match map[key] {
        Json::Object(inner) => _set_nested(inner, keys, idx + 1, value)
        _ => raise dup_key_error(0, key)
      }
    } else {
      let inner : Map[String, Json] = Map::new()
      _set_nested(inner, keys, idx + 1, value)
      map[key] = Json::object(inner)
    }
  }
}

///|
fn ensure_table_path(root : Map[String, Json], keys : Array[String]) -> Map[String, Json] raise ParseError {
  let mut current = root
  let mut i = 0
  while i < keys.length() {
    let key = keys[i]
    if current.contains(key) {
      match current[key] {
        Json::Object(inner) => {
          current = inner
        }
        _ => raise dup_key_error(0, key)
      }
    } else {
      let new_map : Map[String, Json] = Map::new()
      current[key] = Json::object(new_map)
      current = new_map
    }
    i += 1
  }
  current
}

// --------------- Public API ---------------

///|
/// Parse TOML text into a JSON value.
/// Returns a Json::Object containing the parsed key-value pairs.
pub fn parse(text : String) -> Json raise ParseError {
  let tokens = lex(text)
  let root : Map[String, Json] = Map::new()
  let mut pos : ref[Int] = ref[Int](0)
  let mut current_map = root

  while pos.val < tokens.length() {
    consume_newlines(tokens, pos)
    if pos.val >= tokens.length() || tokens[pos.val] is Token::Eof {
      break
    }
    if tokens[pos.val] is Token::TableStart {
      let table_keys = parse_table_header(tokens, pos)
      current_map = ensure_table_path(root, table_keys)
    } else {
      let (keys, value) = parse_key_value(tokens, pos)
      set_nested(current_map, keys, value)
    }
  }
  Json::object(root)
}
