suberror ParseError {
  InvalidToken(Int, String)
  DuplicateKey(Int, String)
  Unexpected(Int, String)
  UnterminatedString(Int)
} derive(Debug)

///|
fn parse_error(pos : Int, msg : String) -> ParseError {
  ParseError::InvalidToken(pos, msg)
}

///|
fn dup_key_error(pos : Int, key : String) -> ParseError {
  ParseError::DuplicateKey(pos, key)
}

// --------------- helpers ---------------

///|
fn is_ident_char(c : Char) -> Bool {
  c.is_alphanumeric() || c == '_' || c == '-'
}

///|
fn is_ws_or_comment(text : String, i : Int) -> Bool {
  if i >= text.length() {
    return false
  }
  let c = text[i]
  c == ' ' || c == '\t' || c == '\r'
}

///|
fn skip_line(text : String, i : ref[Int]) {
  while i.val < text.length() && text[i.val] != '\n' {
    i.val += 1
  }
}

///|
fn skip_ws(text : String, pos : ref[Int]) {
  while pos.val < text.length() && (text[pos.val] == ' ' || text[pos.val] == '\t' || text[pos.val] == '\r') {
    pos.val += 1
  }
}

///|
fn skip_newline(text : String, pos : ref[Int]) {
  while pos.val < text.length() && text[pos.val] == '\n' {
    pos.val += 1
  }
}

///|
fn skip_ws_and_nl(text : String, pos : ref[Int]) {
  skip_ws(text, pos)
  skip_newline(text, pos)
  skip_ws(text, pos)
}

///|
fn char_at(text : String, i : Int) -> Char {
  // use get_char which returns Char?
  let ch = text.get_char(i)
  match ch {
    Some(c) => c
    None => '\u{0000}'
  }
}

// --------------- parser ---------------

///|
fn parse_entry(text : String, pos : ref[Int], current_table : Map[String, Json],
               root : Map[String, Json]) -> Unit raise ParseError {
  skip_ws(text, pos)
  // read key(s)
  let mut keys : Array[String] = []
  // first key segment
  let start = pos.val
  if pos.val < text.length() && text[pos.val] == '"' {
    // quoted key
    let s = parse_string(text, pos)
    keys.push(s)
  } else {
    while pos.val < text.length() && is_ident_char(char_at(text, pos.val)) {
      pos.val += 1
    }
    if pos.val == start {
      raise parse_error(pos.val, "expected key")
    }
    let key = text.sub(start=start, end=pos.val).to_owned()
    keys.push(key)
  }
  skip_ws(text, pos)
  // dotted keys
  while pos.val < text.length() && text[pos.val] == '.' {
    pos.val += 1
    skip_ws(text, pos)
    let ks = pos.val
    if pos.val < text.length() && text[pos.val] == '"' {
      let s = parse_string(text, pos)
      keys.push(s)
    } else {
      while pos.val < text.length() && is_ident_char(char_at(text, pos.val)) {
        pos.val += 1
      }
      if pos.val == ks {
        raise parse_error(pos.val, "expected key after dot")
      }
      keys.push(text.sub(start=ks, end=pos.val).to_owned())
    }
    skip_ws(text, pos)
  }
  // expect '='
  if pos.val >= text.length() || text[pos.val] != '=' {
    raise parse_error(pos.val, "expected '='")
  }
  pos.val += 1
  skip_ws(text, pos)
  let value = parse_value(text, pos)
  // set value in current_table using keys
  set_nested(current_table, keys, value)
  // after value, expect newline or eof
  skip_ws_and_nl(text, pos)
}

///|
fn parse_value(text : String, pos : ref[Int]) -> Json raise ParseError {
  skip_ws(text, pos)
  if pos.val >= text.length() {
    raise parse_error(pos.val, "unexpected end of input")
  }
  let ch = text[pos.val]
  if ch == '"' {
    let s = parse_string(text, pos)
    Json::string(s)
  } else if ch == '[' {
    pos.val += 1
    let mut arr : Array[Json] = []
    skip_ws_and_nl(text, pos)
    if pos.val < text.length() && text[pos.val] == ']' {
      pos.val += 1
      return Json::array(arr)
    }
    loop {
      let val = parse_value(text, pos)
      arr.push(val)
      skip_ws_and_nl(text, pos)
      if pos.val < text.length() && text[pos.val] == ',' {
        pos.val += 1
        skip_ws_and_nl(text, pos)
        if pos.val < text.length() && text[pos.val] == ']' {
          pos.val += 1
          break
        }
      } else if pos.val < text.length() && text[pos.val] == ']' {
        pos.val += 1
        break
      } else {
        raise parse_error(pos.val, "expected ',' or ']' in array")
      }
    }
    Json::array(arr)
  } else if ch == 't' {
    if text.sub(start=pos.val, end=pos.val + 4).to_owned() == "true" {
      pos.val += 4
      Json::boolean(true)
    } else {
      raise parse_error(pos.val, "expected 'true'")
    }
  } else if ch == 'f' {
    if text.sub(start=pos.val, end=pos.val + 5).to_owned() == "false" {
      pos.val += 5
      Json::boolean(false)
    } else {
      raise parse_error(pos.val, "expected 'false'")
    }
  } else if ch.is_digit() || ch == '-' || ch == '+' {
    let start = pos.val
    if ch == '-' || ch == '+' {
      pos.val += 1
    }
    while pos.val < text.length() && (text[pos.val].is_digit() || text[pos.val] == '_') {
      if text[pos.val] != '_' {
        pos.val += 1
      } else {
        pos.val += 1
      }
    }
    let num_str = text.sub(start=start, end=pos.val).to_owned()
    // strip underscores
    let clean = num_str.replace("_", "")
    let n : Int = @string.from_str(clean) catch {
      _ => raise parse_error(start, "invalid integer: " + clean)
    }
    Json::number(n.to_double())
  } else {
    raise parse_error(pos.val, "unexpected character")
  }
}

///|
fn parse_string(text : String, pos : ref[Int]) -> String raise ParseError {
  if pos.val >= text.length() || text[pos.val] != '"' {
    raise parse_error(pos.val, "expected '\"'")
  }
  pos.val += 1
  let mut sb = StringBuilder::new()
  while pos.val < text.length() {
    let c = text[pos.val]
    if c == '"' {
      pos.val += 1
      return sb.to_string()
    } else if c == '\\' {
      pos.val += 1
      if pos.val >= text.length() {
        raise ParseError::UnterminatedString(pos.val)
      }
      let esc = text[pos.val]
      if esc == '"' { sb.write_char('"') }
      else if esc == '\\' { sb.write_char('\\') }
      else if esc == 'n' { sb.write_char('\n') }
      else if esc == 't' { sb.write_char('\t') }
      else { sb.write_char(esc.to_char()) }
      pos.val += 1
    } else if c == '\n' {
      raise ParseError::UnterminatedString(pos.val)
    } else {
      sb.write_char(c.to_char())
      pos.val += 1
    }
  }
  raise ParseError::UnterminatedString(pos.val)
}

// --------------- nested map helpers ---------------

///|
fn set_nested(map : Map[String, Json], keys : Array[String], value : Json) raise ParseError {
  _set_nested(map, keys, 0, value)
}

///|
fn _set_nested(map : Map[String, Json], keys : Array[String], idx : Int, value : Json) raise ParseError {
  if idx == keys.length() - 1 {
    let key = keys[idx]
    if map.contains(key) {
      raise dup_key_error(0, key)
    }
    map[key] = value
  } else {
    let key = keys[idx]
    if map.contains(key) {
      match map[key] {
        Json::Object(inner) => _set_nested(inner, keys, idx + 1, value)
        _ => raise dup_key_error(0, key)
      }
    } else {
      let inner : Map[String, Json] = Map::new()
      _set_nested(inner, keys, idx + 1, value)
      map[key] = Json::object(inner)
    }
  }
}

///|
fn ensure_table_path(root : Map[String, Json], keys : Array[String]) -> Map[String, Json] raise ParseError {
  let mut current = root
  let mut i = 0
  while i < keys.length() {
    let key = keys[i]
    if current.contains(key) {
      match current[key] {
        Json::Object(inner) => {
          current = inner
        }
        _ => raise dup_key_error(0, key)
      }
    } else {
      let new_map : Map[String, Json] = Map::new()
      current[key] = Json::object(new_map)
      current = new_map
    }
    i += 1
  }
  current
}

// --------------- Public API ---------------

///|
pub fn parse(text : String) -> Json raise ParseError {
  let root : Map[String, Json] = Map::new()
  let mut current_table = root
  let mut pos : ref[Int] = ref[Int](0)

  while pos.val < text.length() {
    // skip whitespace, newlines, comments
    skip_ws_and_nl(text, pos)
    if pos.val >= text.length() {
      break
    }
    if text[pos.val] == '#' {
      skip_line(text, pos)
      continue
    }
    if text[pos.val] == '[' {
      // table header
      pos.val += 1
      // read keys until ']'
      let mut table_keys : Array[String] = []
      skip_ws(text, pos)
      // first key
      if pos.val < text.length() && text[pos.val] == '"' {
        let s = parse_string(text, pos)
        table_keys.push(s)
      } else {
        let start = pos.val
        while pos.val < text.length() && is_ident_char(char_at(text, pos.val)) {
          pos.val += 1
        }
        if pos.val == start {
          raise parse_error(pos.val, "expected key in table header")
        }
        table_keys.push(text.sub(start=start, end=pos.val).to_owned())
      }
      skip_ws(text, pos)
      // dotted parts
      while pos.val < text.length() && text[pos.val] == '.' {
        pos.val += 1
        skip_ws(text, pos)
        let ks = pos.val
        if pos.val < text.length() && text[pos.val] == '"' {
          let s = parse_string(text, pos)
          table_keys.push(s)
        } else {
          while pos.val < text.length() && is_ident_char(char_at(text, pos.val)) {
            pos.val += 1
          }
          if pos.val == ks {
            raise parse_error(pos.val, "expected key after dot in table header")
          }
          table_keys.push(text.sub(start=ks, end=pos.val).to_owned())
        }
        skip_ws(text, pos)
      }
      if pos.val >= text.length() || text[pos.val] != ']' {
        raise parse_error(pos.val, "expected ']'")
      }
      pos.val += 1
      skip_ws_and_nl(text, pos)
      current_table = ensure_table_path(root, table_keys)
    } else {
      parse_entry(text, pos, current_table, root)
    }
  }
  Json::object(root)
}

///|
fn Char.is_digit() -> Bool {
  self.to_int() >= 48 && self.to_int() <= 57
}
