  while pos.val < text.length() && text[pos.val] == '\n' {
    pos.val += 1
  }
}

///|
fn skip_ws_nl_comment(text : String, pos : Pos) -> Unit {
  loop {
    skip_ws(text, pos)
    skip_newlines(text, pos)
    if pos.val < text.length() && text[pos.val] == '#' {
      skip_line(text, pos)
    } else {
      break
    }
  }
}

// --------------- parser ---------------

///|
fn parse_entry(text : String, pos : Pos, current_table : Map[String, Json]) -> Unit raise ParseError {
  let keys : Array[String] = []
  read_key(text, pos, keys)
  skip_ws(text, pos)
  while pos.val < text.length() && text[pos.val] == '.' {
    pos.val += 1
    skip_ws(text, pos)
    read_key_segment(text, pos, keys)
    skip_ws(text, pos)
  }
  if pos.val >= text.length() || text[pos.val] != '=' {
    raise parse_error(pos.val, "expected '='")
  }
  pos.val += 1
  skip_ws(text, pos)
  let value = parse_value(text, pos)
  set_nested(current_table, keys, value)
  skip_ws_nl_comment(text, pos)
}

///|
fn read_key(text : String, pos : Pos, keys : Array[String]) -> Unit raise ParseError {
  if pos.val >= text.length() {
    raise parse_error(pos.val, "expected key")
  }
  if text[pos.val] == '"' {
    let s = parse_string(text, pos)
    keys.push(s)
  } else {
    read_key_segment(text, pos, keys)
  }
}

///|
fn read_key_segment(text : String, pos : Pos, keys : Array[String]) -> Unit raise ParseError {
  let start = pos.val
  if pos.val < text.length() && text[pos.val] == '"' {
    let s = parse_string(text, pos)
    keys.push(s)
    return
  }
  while pos.val < text.length() && is_ident_continue(char_at(text, pos.val)) {
    pos.val += 1
  }
  if pos.val == start {
    raise parse_error(pos.val, "expected key")
  }
  keys.push(text.sub(start=start, end=pos.val).to_owned())
}

///|
fn parse_value(text : String, pos : Pos) -> Json raise ParseError {
  skip_ws(text, pos)
  if pos.val >= text.length() {
    raise parse_error(pos.val, "unexpected end of input")
  }
  let ch = text[pos.val]
  if ch == '"' {
    let s = parse_string(text, pos)
    Json::string(s)
  } else if ch == '[' {
    pos.val += 1
    let arr : Array[Json] = []
    skip_ws_nl_comment(text, pos)
    if pos.val < text.length() && text[pos.val] == ']' {
      pos.val += 1
      return Json::array(arr)
    }
    while true {
      let val = parse_value(text, pos)
      arr.push(val)
      skip_ws_nl_comment(text, pos)
      if pos.val < text.length() && text[pos.val] == ',' {
        pos.val += 1
        skip_ws_nl_comment(text, pos)
        if pos.val < text.length() && text[pos.val] == ']' {
          pos.val += 1
          break
        }
      } else if pos.val < text.length() && text[pos.val] == ']' {
        pos.val += 1
        break
      } else {
        raise parse_error(pos.val, "expected ',' or ']' in array")
      }
    }
    Json::array(arr)
  } else if ch == 't' {
    if pos.val + 4 <= text.length() && text.sub(start=pos.val, end=pos.val + 4).to_owned() == "true" {
      pos.val += 4
      Json::boolean(true)
    } else {
      raise parse_error(pos.val, "expected 'true'")
    }
  } else if ch == 'f' {
    if pos.val + 5 <= text.length() && text.sub(start=pos.val, end=pos.val + 5).to_owned() == "false" {
      pos.val += 5
      Json::boolean(false)
    } else {
      raise parse_error(pos.val, "expected 'false'")
    }
  } else if ch == '-' || ch == '+' || is_digit_char(ch) {
    let start = pos.val
    if ch == '-' || ch == '+' {
      pos.val += 1
    }
    while pos.val < text.length() {
      let c = char_at(text, pos.val)
      if c.is_ascii_digit() || c == '_' {
        pos.val += 1
      } else {
        break
      }
    }
    let num_str = text.sub(start=start, end=pos.val).to_owned()
    let clean = num_str.replace(old="_", new="")
    let n : Int = @string.from_str(clean) catch {
      _ => raise parse_error(start, "invalid integer: " + clean)
    }
    Json::number(n.to_double())
  } else {
    raise parse_error(pos.val, "unexpected character")
  }
}

///|
fn is_digit_char(c : UInt16) -> Bool {
  c >= 48 && c <= 57
}

///|
fn parse_string(text : String, pos : Pos) -> String raise ParseError {
  if pos.val >= text.length() || text[pos.val] != '"' {
    raise parse_error(pos.val, "expected '\"'")
  }
  pos.val += 1
  let sb = StringBuilder::new()
  while pos.val < text.length() {
    let c = text[pos.val]
    if c == '"' {
      pos.val += 1
      return sb.to_string()
    } else if c == '\\' {
      pos.val += 1
      if pos.val >= text.length() {
        raise ParseError::UnterminatedString(pos.val)
      }
      let esc = text[pos.val]
      if esc == '"' { sb.write_char('"') }
      else if esc == '\\' { sb.write_char('\\') }
      else if esc == 'n' { sb.write_char('\n') }
      else if esc == 't' { sb.write_char('\t') }
      else { sb.write_char(char_at(text, pos.val)) }
      pos.val += 1
    } else if c == '\n' {
      raise ParseError::UnterminatedString(pos.val)
    } else {
      match text.get_char(pos.val) {
        Some(ch) => sb.write_char(ch)
        None => raise ParseError::UnterminatedString(pos.val)
      }
      pos.val += 1
    }
  }
  raise ParseError::UnterminatedString(pos.val)
}

// --------------- nested map helpers ---------------

///|
fn set_nested(map : Map[String, Json], keys : Array[String], value : Json) -> Unit raise ParseError {
  _set_nested(map, keys, 0, value)
}

///|
fn _set_nested(map : Map[String, Json], keys : Array[String], idx : Int, value : Json) -> Unit raise ParseError {
  let key = keys[idx]
  if idx == keys.length() - 1 {
    if map.contains(key) {
      raise dup_key_error(0, key)
    }
    map[key] = value
  } else {
    if map.contains(key) {
      match map[key] {
        Json::Object(inner) => _set_nested(inner, keys, idx + 1, value)
        _ => raise dup_key_error(0, key)
      }
    } else {
      let inner : Map[String, Json] = Map::new()
      _set_nested(inner, keys, idx + 1, value)
      map[key] = Json::object(inner)
    }
  }
}

///|
fn ensure_table_path(root : Map[String, Json], keys : Array[String]) -> Map[String, Json] raise ParseError {
  let cur_map : Map[String, Json] = root
  let mut i = 0
  let mut result = cur_map
  while i < keys.length() {
    let key = keys[i]
    if result.contains(key) {
      match result[key] {
        Json::Object(inner) => {
          result = inner
        }
        _ => raise dup_key_error(0, key)
      }
    } else {
      let new_map : Map[String, Json] = Map::new()
      result[key] = Json::object(new_map)
      result = new_map
    }
    i += 1
  }
  result
}

// --------------- Public API ---------------

///|
pub fn parse(text : String) -> Json raise ParseError {
  let root : Map[String, Json] = Map::new()
  let mut current_table = root
  let pos : Pos = { val: 0 }

  skip_ws_nl_comment(text, pos)
  while pos.val < text.length() {
    if text[pos.val] == '[' {
      pos.val += 1
      let table_keys : Array[String] = []
      skip_ws(text, pos)
      read_key(text, pos, table_keys)
      skip_ws(text, pos)
      while pos.val < text.length() && text[pos.val] == '.' {
        pos.val += 1
        skip_ws(text, pos)
        read_key_segment(text, pos, table_keys)
        skip_ws(text, pos)
      }
      if pos.val >= text.length() || text[pos.val] != ']' {
        raise parse_error(pos.val, "expected ']'")
      }
      pos.val += 1
      skip_ws_nl_comment(text, pos)
      current_table = ensure_table_path(root, table_keys)
    } else {
      parse_entry(text, pos, current_table)
    }
    skip_ws_nl_comment(text, pos)
  }
  Json::object(root)
}
"}

